Random number: {{payload}}

This is the payload: 
<p>
<i>{{payload.mystring}}</i>,
</p><p>
<b class="newclass">{{payload.mynumber}}</b>.
</p>

<style>
    /* Dynamically inserted CSS class */
    .newclass {
        background-color: yellow;
        padding:1em;
    }
</style>

<script>
    // Dynamically inserted script
    // Runs on every insert.
    console.log('Live script in inserted HTML')
    uibuilder.send({payload: 'WOW! This is from an inserted script!'})

    /** To get a dynamically inserted script
     * to only run once
     */
    if (!window._someuniquename) {
        console.log('This is only ever run once. It wont run again unless the page is reloaded.')

        // Set the flag true so wont run again
        window._someuniquename = true
    }
</script>

