/**
 * This function sends several messages to a uibuilder
 * node.
 * 
 * NOTE that we add topics to each sent message in case we
 * want to use the `uib-cache` node to save and replay
 * on reload.
 * 
 * OK so it might seem like I'm cheating here since this is
 * obviously not "no-code". 😊 However, you CAN do all of
 * this without code, it's just a bit more messy in the flow
 * and this example flow is already very large.
 * 
 * Really, this is just sending 3 different messages, nothing else.
 * So it is mostly data and not really code. 😉
 */

/**
 * Dynamically load the MarkdownIT library to allow
 * rendering of Markdown. Also load the HightlightJS
 * & markdownTaskLists plugins.
 * 
 * We are loading from the Internet here. Use uibuilder's
 * library manager to install locally and then change URL's
 * to start with `../uibuilder/vendor/` instead of
 * `https://cdn.jsdelivr.net/gh/` or `https://cdn.jsdelivr.net/npm/`
 * and remove `@latest`.
 * 
 * This uses uibuilder's low-code UI feature.
 */
node.send({
    "topic": "load-markdownit-cdn",
    "_ui": { 
        "method": "load", 
        "srcStyles": [
            // The styles for code highlighting
            "https://cdn.jsdelivr.net/gh/highlightjs/cdn-release@latest/build/styles/hybrid.min.css"
        ],
        "srcScripts": [
            // The plugin for highlighting
            "https://cdn.jsdelivr.net/gh/highlightjs/cdn-release@latest/build/highlight.min.js",
            // Markdown-IT itself
            "https://cdn.jsdelivr.net/npm/markdown-it@latest/dist/markdown-it.min.js",
            // A plugin for GitHub style task lists
            "https://cdn.jsdelivr.net/npm/markdown-it-task-lists@latest/dist/markdown-it-task-lists.min.js"
        ]
    }
})

/**
 * Now add the task list plugin to the list of used MarkdownIT
 * plugins. Note that we don't have to do that for the Highlight
 * plugin because MarkdownIT does that internally.
 * 
 * This is a uibuilder remote command.
 */
node.send({
    "topic": "use-markdownit-plugins",
    "_uib": { 
        // We are setting a uib managed variable in the browser
        "command": "set",
        // This variable name is reserved for loading MarkdownIT plugins
        "prop": "ui_md_plugins",
        // The value must be an ARRAY
        "value": [
            { "markdownitTaskLists": { "enabled": true } }
        ],
        // Set this otherwise the command result is replayed to us
        "quiet": true
    }
})

/**
 * Now lets get clever and dynamically add some browser code
 * that will report back to Node-RED when a task list entry
 * is clicked.
 * 
 * We have to send the code as text so we set that up first.
 * The UI command adds a new `<script>` tag in the attached clients
 * which runs immediately it is loaded. It adds a "change" event
 * listener to the `<body>` tag that listens for changes to the
 * checkboxes that the markdownitTaskLists plugin dynamically
 * creates when the markdown is converted to HTML.
 * 
 * We do it this way so that it doesn't matter WHEN the markdown
 * is rendered. Even if we add new checkboxes later, they will
 * still respond.
 * 
 * The returned payload tells us whether the entry is (un-)checked,
 * What the text of the changed list entry is, and what number
 * entry in the list was changed.
 */
const mycode = `
// Add to body element so that checkboxes added late are still picked up
$('body').addEventListener('change', (event) => {
    /** @type {HTMLInputElement} */
    const el = event.target
    if (el.classList.contains('task-list-item-checkbox')) {
        const changedList = el.closest('.contains-task-list')
        const changedListItem = el.closest('.task-list-item')
        const changedEntryNumber = Array.from(changedList.children).indexOf(changedListItem) + 1;

        // console.log([el.checked, el.nextSibling.textContent, changedEntryNumber ])

        uibuilder.send({
            'topic': 'markdown-checkbox-clicked',
            payload: {
                'checked': el.checked,
                'entryText': el.nextSibling.textContent,
                'entryOffset': changedEntryNumber
            }
        })
    }
})
`
node.send({
    "topic": "add-listener-script",
    // Another uibuilder low-code command
    "_ui": {
        "method": "load",
        "txtScripts": [
            mycode,
        ]
    }
})

